window.AUTH=window.AUTH||{};window.AUTH["19-547"]={"d":"19-547","id":"2020/19-547","n":"U.S. Fish and Wildlife Service v. Sierra Club","briefs":[{"k":"petitioner","label":"Brief of petitioners United States Fish and Wildlife Service, et al.","date":"2020-05-21","url":"https://www.supremecourt.gov/DocketPDF/19/19-547/144037/20200521185300042_19-547tsUnitedStates.pdf","side":"pet","n":46},{"k":"respondent","label":"Brief of respondent Sierra Club, Inc.","date":"2020-07-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-547/148790/20200727162401210_19-547%20-%20Brief%20for%20Respondent%20Sierra%20Club.pdf","side":"res","n":88},{"k":"reply","label":"Reply of petitioners United States Fish and Wildlife Service, et al.","date":"2020-08-26","url":"https://www.supremecourt.gov/DocketPDF/19/19-547/151395/20200826183521888_19-547rbUnitedStates.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-547_new_3e04.pdf","tr":true,"items":[{"t":"case","label":"Abdelfattah v. U.S. Dep’t of Homeland Sec.","cite":"488 F.3d 178","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/488/178/","by":{"0":"4"}},{"t":"case","label":"Abtew v. United States Dep’t of Homeland Sec.","cite":"808 F.3d 895","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/808/895/","by":{"0":"19, 29, 35, 47"},"q":[{"src":"brief","b":0,"text":"classic example[s] of a deliberative document.","cite":"808 F.3d 895, 899"},{"src":"brief","b":0,"text":"[a] recommendation to a supervisor on a matter pending before the supervisor is a classic example of a deliberative document.","cite":"808 F.3d 895, 899"}]},{"t":"case","label":"American Fed’n of Gov’t Emps. v. U.S. Dep’t of Commerce","cite":"907 F.2d 203","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/907/203/","by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"reflects a preliminary position by the [agency] that was subsequently rejected.","cite":"907 F.2d 203"}]},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"by":{"0":"6, 18, 28, 32","1":"passim","2":"17, 18, 19"},"q":[{"src":"brief","b":1,"text":"The action agency is technically free to disregard the Biological Opinion and proceed with its proposed action.","cite":"520 U.S. at 170"},{"src":"brief","b":2,"text":"alters the legal regime to which the action agency is subject,","cite":"520 U.S. at 169"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"if (but only if ) it complies with the prescribed conditions.","cite":"520 U. S., at 178"},{"src":"argument","who":"Mr. Guarnieri","text":"There -- there are a handful of examples -- so, to -- to step back for a second, the Endangered Species Act -- as -- as the Court discussed in Bennett against Spear, the Endangered Species Act at least theoretically permits an action agency to decide that, notwithstanding the biological opinion, the action agency has decided that its agency's action would not cause jeopardy."},{"src":"argument","who":"Mr. Guarnieri","text":"Well, Justice Sotomayor, to -- to -- to sort of take those questions in -- in sequence, I think it's abundantly clear that in Bennett against Spear, the Court was discussing final biological opinions, as evidenced by the Court's focus on the legal force and effect of the incidental take statement that is issued when the agency -- when the Services render a jeopardy -- excuse me, a no jeopardy opinion."},{"src":"argument","who":"Justice Barrett","text":"So it's not your position that we should adopt some sort of bright line saying, listen, it's not over until it's over, it's not until it's actually issued in the sense of being final, maybe even in the Bennett versus Spear sense of the word?"}]},{"t":"case","label":"City of Virginia Beach v. United States Dep’t of Commerce","cite":"995 F.2d 1247","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/995/1247/","by":{"0":"4"}},{"t":"case","label":"Coastal States Gas Corp. v. Department of Energy","cite":"617 F.2d 854","y":1980,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/617/854/","by":{"0":"3, 24","1":"passim","2":"7"},"q":[{"src":"brief","b":0,"text":"draft[s] of what will become a final document","cite":"617 F.2d 854, 866"},{"src":"brief","b":1,"text":"used . . . in the discharge of [their] regulatory duties . . . hidden behind a veil of privilege because [they are] not designated as ‘formal,’ binding,’ or ‘final.’","cite":"617 F.2d at 867"},{"src":"brief","b":2,"text":"adopted, formally or informally, as the agency position.","cite":"617 F.2d 854, 866"}]},{"t":"case","label":"Cooling Water Intake Structure Coal. v. United States Envtl. Prot. Agency","cite":"905 F.3d 49","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/905/49/","by":{"0":"11, 12, 35","1":"12, 13, 14, 15, 16"}},{"t":"case","label":"Department of the Interior v. Klamath Water Users Protective Ass’n","cite":"532 U.S. 1","y":2001,"id":"2000/99-1871","sc":1,"by":{"0":"2, 3, 23, 34, 44","1":"47, 54","2":"13"},"q":[{"src":"brief","b":0,"text":"unless the documents fall within enumerated exceptions.","cite":"532 U.S. 1, 7"},{"src":"brief","b":0,"text":"will not communicate candidly among themselves","cite":"532 U.S. 1, 8-9"},{"src":"brief","b":1,"text":"enhance ‘the quality of agency decisions.’","cite":"532 U.S. 1, 9"}]},{"t":"case","label":"EPA v. Mink","cite":"410 U.S. 73","y":1973,"id":"1972/71-909","sc":1,"by":{"0":"4, 23, 24","1":"6, 44, 46, 48","2":"19, 22"},"q":[{"src":"brief","b":0,"text":"permit inquiry into particularized needs of the individual seeking the information, although such an inquiry would ordinarily be made of a private litigant.","cite":"410 U.S. 73, 86"},{"src":"brief","b":1,"text":"delimit[s] the exception as narrowly as consistent with efficient Government operation.","cite":"410 U.S. 73, 87"},{"src":"brief","b":1,"text":"as narrowly as consistent with efficient Government operation.","cite":"410 U.S. at 87"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"forced to operate in a fishbowl,","cite":"410 U. S. 73, 87"}]},{"t":"case","label":"FTC v. Grolier Inc.","cite":"462 U.S. 19","y":1983,"id":"1982/82-372","sc":1,"by":{"0":"4"},"q":[{"src":"brief","b":0,"text":"party’s need * * * would be sufficient to override the privilege","cite":"462 U.S. 19, 28"}]},{"t":"case","label":"Federal Open Mkt. Comm. of the Fed. Reserve Sys. v. Merrill","cite":"443 U.S. 340","y":1979,"id":"1978/77-1387","sc":1,"by":{"0":"23","1":"40, 51"},"q":[{"src":"brief","b":1,"text":"any memoranda, even those that contain final opinions and statements of policy, whenever the agency concluded that disclosure would not promote the ‘efficiency’ of its operations or otherwise would not be in the ‘public interest’","cite":"443 U.S. at 354"}]},{"t":"case","label":"Florida House of Representatives v. United States Dep’t of Commerce","cite":"961 F.2d 941","y":1992,"url":"https://www.courtlistener.com/c/F.2d/961/941/","by":{"0":"4, 26, 39, 47"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"as much a part of FOIA’s purposes and policies as the statute’s disclosure requirement.","cite":"139 S. Ct. 2356, 2366"}]},{"t":"case","label":"John Doe Agency v. John Doe Corp.","cite":"493 U.S. 146","y":1989,"id":"1989/88-1083","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"workable balance between the right of the public to know and the need of the Government to keep information in confidence to the extent necessary without permitting indiscriminate secrecy.","cite":"493 U.S. 146, 152"}]},{"t":"case","label":"Lead Indus. Ass’n v. OSHA","cite":"610 F.2d 70","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/610/70/","by":{"0":"4, 45"}},{"t":"case","label":"Mobil Oil Corp. v. United States Envtl. Prot. Agency","cite":"879 F.2d 698","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/879/698/","by":{"0":"47","2":"14"}},{"t":"case","label":"NLRB v. Sears, Roebuck & Co.","cite":"421 U.S. 132","y":1975,"id":"1974/73-1233","sc":1,"by":{"0":"passim","1":"passim","2":"3, 6, 7, 15, 19"},"q":[{"src":"brief","b":0,"text":"documents reflecting advisory opinions, recommendations and deliberations comprising part of a process by which governmental decisions and policies are formulated.","cite":"421 U.S. at 150"},{"src":"brief","b":0,"text":"‘reflecting * * * recommendations and deliberations’","cite":"421 U.S. at 150"},{"src":"brief","b":1,"text":"supply the basis for an agency policy actually adopted.","cite":"421 U.S. 132, 152-53"},{"src":"brief","b":1,"text":"the reasons which did supply the basis for an agency policy actually adopted.","cite":"421 U.S. at 152"},{"src":"brief","b":2,"text":"by which governmental decisions and policies are formulated,","cite":"421 U.S. at 150"},{"src":"brief","b":2,"text":"to the detriment of the decisionmaking process.","cite":"421 U.S. at 150"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"documents reflecting advisory opinions, recommendations and deliberations comprising part of a process by which governmental decisions and policies are formulated,","cite":"421 U. S. 132, 150"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"in the context of the administrative process which generated them.","cite":"421 U. S., at 138"}]},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"by":{"0":"32","1":"passim","2":"13"}},{"t":"case","label":"National Sec. Archive v. CIA","cite":"752 F.3d 460","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/752/460/","by":{"0":"passim","1":"35, 36","2":"2, 3, 19, 20, 21"},"q":[{"src":"brief","b":0,"text":"‘is still a draft and thus still pre-decisional and deliberative.’","cite":"752 F.3d at 463"},{"src":"brief","b":0,"text":"draft is still a draft and thus still pre-decisional and deliberative.","cite":"752 F.3d at 463"},{"src":"brief","b":2,"text":"judged by what they decided, not for matters they considered before making up their minds.","cite":"752 F.3d at 462"},{"src":"brief","b":2,"text":"that the privilege will apply and that [a] draft will remain confidential,","cite":"752 F.3d at 463"}]},{"t":"case","label":"National Wildlife Fed’n v. United States Forest Serv.","cite":"861 F.2d 1114","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/861/1114/","by":{"0":"4, 26, 45"},"q":[{"src":"brief","b":0,"text":"[s]ubjecting a policymaker to public criticism on the basis of such tentative assessments is precisely what the deliberative process privilege is intended to prevent.","cite":"861 F.2d at 1120"}]},{"t":"case","label":"Renegotiation Bd. v. Grumman Aircraf t Eng’g Corp.","cite":"421 U.S. 168","y":1975,"id":"1974/73-1316","sc":1,"by":{"0":"passim","1":"31, 49, 50, 52, 53","2":"3, 4, 7, 10, 15, 16"},"q":[{"src":"brief","b":0,"text":"distinguish[es] between predecisional memoranda prepared in order to assist an agency decision-maker in arriving at his decision, which are exempt from disclosure, and postdecisional memoranda setting forth the reasons for an agency decision already made, which are not.","cite":"421 U.S. 168, 184"},{"src":"brief","b":0,"text":"setting forth the reasons for an agency decision already made,","cite":"421 U.S. at 184"},{"src":"brief","b":2,"text":"the reasons for an agency decision already made,","cite":"421 U.S. 168, 184"},{"src":"brief","b":2,"text":"predecisional memoranda prepared in order to assist an agency decision-maker in arriving at his decision, which are exempt from disclosure, and postdecisional memoranda setting forth the reasons for an agency decision already made, which are not.","cite":"421 U.S. at 184"}]},{"t":"case","label":"Schell v. United States Dep’t of Health & Human Servs.","cite":"843 F.2d 933","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/843/933/","by":{"0":"39"}},{"t":"case","label":"Town of Norfolk v. United States Army Corps of Eng’rs","cite":"968 F.2d 1438","y":1992,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/968/1438/","by":{"0":"4, 35"}},{"t":"case","label":"United States v. Nixon","cite":"41 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"0":"24"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"id":"2015/15-290","sc":1,"by":{"0":"32"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"7"}},{"t":"usc","label":"33 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/33/1326","subs":["(b)"],"stext":{"head":"§1326. Thermal discharges","paras":[[0,"(a) Effluent limitations that will assure protection and propagation of balanced, indigenous population of shellfish, fish, and wildlife"],[0,"With respect to any point source otherwise subject to the provisions of section 1311 of this title or section 1316 of this title, whenever the owner or operator of any such source, after opportunity for public hearing, can demonstrate to the satisfaction of the Administrator (or, if appropriate, the State) that any effluent limitation proposed for the control of the thermal component of any discharge from such source will require effluent limitations more stringent than necessary to assure the projection and propagation of a balanced, indigenous population of shellfish, fish, and wildlife in and on the body of water into which the discharge is to be made, the Administrator (or, if appropriate, the State) may impose an effluent limitation under such sections for such plant, with respect to the thermal component of such discharge (taking into account the interaction of such thermal component with other pollutants), that will assure the protection and propagation of a balanced, indigenous population of shellfish, fish, and wildlife in and on that body of water."],[0,"(b) Cooling water intake structures"],[0,"Any standard established pursuant to section 1311 of this title or section 1316 of this title and applicable to a point source shall require that the location, design, construction, and capacity of cooling water intake structures reflect the best technology available for minimizing adverse environmental impact."],[0,"(c) Period of protection from more stringent effluent limitations following discharge point source modification commenced after October 18, 1972"],[0,"Notwithstanding any other provision of this chapter, any point source of a discharge having a thermal component, the modification of which point source is commenced after October 18, 1972, and which, as modified, meets effluent limitations established under section 1311 of this title or, if more stringent, effluent limitations established under section 1313 of this title and which effluent limitations will assure protection and propagation of a balanced, indigenous population of shellfish, fish, and wildlife in or on the water into which the discharge is made, shall not be subject to any more stringent effluent limitation with respect to the thermal component of its discharge during a ten year period beginning on the date of completion of such modification or during the period of depreciation or amortization of such facility for the purpose of section 167 or 169 (or both) of title 26, whichever period ends first."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1326?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8","1":"12"}},{"t":"usc","label":"16 U.S.C. § 1531","url":"https://www.law.cornell.edu/uscode/text/16/1531","stext":{"head":"§1531. Congressional findings and declaration of purposes and policy","paras":[[0,"(a) Findings"],[0,"The Congress finds and declares that—"],[1,"(1) various species of fish, wildlife, and plants in the United States have been rendered extinct as a consequence of economic growth and development untempered by adequate concern and conservation;"],[1,"(2) other species of fish, wildlife, and plants have been so depleted in numbers that they are in danger of or threatened with extinction;"],[1,"(3) these species of fish, wildlife, and plants are of esthetic, ecological, educational, historical, recreational, and scientific value to the Nation and its people;"],[1,"(4) the United States has pledged itself as a sovereign state in the international community to conserve to the extent practicable the various species of fish or wildlife and plants facing extinction, pursuant to—"],[2,"(A) migratory bird treaties with Canada and Mexico;"],[2,"(B) the Migratory and Endangered Bird Treaty with Japan;"],[2,"(C) the Convention on Nature Protection and Wildlife Preservation in the Western Hemisphere;"],[2,"(D) the International Convention for the Northwest Atlantic Fisheries;"],[2,"(E) the International Convention for the High Seas Fisheries of the North Pacific Ocean;"],[2,"(F) the Convention on International Trade in Endangered Species of Wild Fauna and Flora; and"],[2,"(G) other international agreements; and"],[1,"(5) encouraging the States and other interested parties, through Federal financial assistance and a system of incentives, to develop and maintain conservation programs which meet national and international standards is a key to meeting the Nation's international commitments and to better safeguarding, for the benefit of all citizens, the Nation's heritage in fish, wildlife, and plants."],[0,"(b) Purposes"],[0,"The purposes of this chapter are to provide a means whereby the ecosystems upon which endangered species and threatened species depend may be conserved, to provide a program for the conservation of such endangered species and threatened species, and to take such steps as may be appropriate to achieve the purposes of the treaties and conventions set forth in subsection (a) of this section."],[0,"(c) Policy"],[0,"(1) It is further declared to be the policy of Congress that all Federal departments and agencies shall seek to conserve endangered species and threatened species and shall utilize their authorities in furtherance of the purposes of this chapter."],[0,"(2) It is further declared to be the policy of Congress that Federal agencies shall cooperate with State and local agencies to resolve water resource issues in concert with conservation of endangered species."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1531?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","2":"5"}},{"t":"usc","label":"16 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/16/1536","subs":["(a)(2)","(b)(3)(A)","(b)(4)","(a)(3)","(b)(4)(A)","(e)","(o)(2)"],"stext":{"head":"§1536. Interagency cooperation","paras":[[0,"(a) Federal agency actions and consultations"],[0,"(1) The Secretary shall review other programs administered by him and utilize such programs in furtherance of the purposes of this chapter. All other Federal agencies shall, in consultation with and with the assistance of the Secretary, utilize their authorities in furtherance of the purposes of this chapter by carrying out programs for the conservation of endangered species and threatened species listed pursuant to section 1533 of this title."],[0,"(2) Each Federal agency shall, in consultation with and with the assistance of the Secretary, insure that any action authorized, funded, or carried out by such agency (hereinafter in this section referred to as an \"agency action\") is not likely to jeopardize the continued existence of any endangered species or threatened species or result in the destruction or adverse modification of habitat of such species which is determined by the Secretary, after consultation as appropriate with affected States, to be critical, unless such agency has been granted an exemption for such action by the Committee pursuant to subsection (h) of this section. In fulfilling the requirements of this paragraph each agency shall use the best scientific and commercial data available."],[0,"(3) Subject to such guidelines as the Secretary may establish, a Federal agency shall consult with the Secretary on any prospective agency action at the request of, and in cooperation with, the prospective permit or license applicant if the applicant has reason to believe that an endangered species or a threatened species may be present in the area affected by his project and that implementation of such action will likely affect such species."],[0,"(4) Each Federal agency shall confer with the Secretary on any agency action which is likely to jeopardize the continued existence of any species proposed to be listed under section 1533 of this title or result in the destruction or adverse modification of critical habitat proposed to be designated for such species. This paragraph does not require a limitation on the commitment of resources as described in subsection (d)."],[0,"(b) Opinion of Secretary"],[0,"(1)(A) Consultation under subsection (a)(2) with respect to any agency action shall be concluded within the 90-day period beginning on the date on which initiated or, subject to subparagraph (B), within such other period of time as is mutually agreeable to the Secretary and the Federal agency."],[0,"(B) In the case of an agency action involving a permit or license applicant, the Secretary and the Federal agency may not mutually agree to conclude consultation within a period exceeding 90 days unless the Secretary, before the close of the 90th day referred to in subparagraph (A)—"],[1,"(i) if the consultation period proposed to be agreed to will end before the 150th day after the date on which consultation was initiated, submits to the applicant a written statement setting forth—"],[2,"(I) the reasons why a longer period is required,"],[2,"(II) the information that is required to complete the consultation, and"],[2,"(III) the estimated date on which consultation will be completed; or"],[1,"(ii) if the consultation period proposed to be agreed to will end 150 or more days after the date on which consultation was initiated, obtains the consent of the applicant to such period."],[0,"The Secretary and the Federal agency may mutually agree to extend a consultation period established under the preceding sentence if the Secretary, before the close of such period, obtains the consent of the applicant to the extension."],[0,"(2) Consultation under subsection (a)(3) shall be concluded within such period as is agreeable to the Secretary, the Federal agency, and the applicant concerned."],[0,"(3)(A) Promptly after conclusion of consultation under paragraph (2) or (3) of subsection (a), the Secretary shall provide to the Federal agency and the applicant, if any, a written statement setting forth the Secretary's opinion, and a summary of the information on which the opinion is based, detailing how the agency action affects the species or its critical habitat. If jeopardy or adverse modification is found, the Secretary shall suggest those reasonable and prudent alternatives which he believes would not violate subsection (a)(2) and can be taken by the Federal agency or applicant in implementing the agency action."],[0,"(B) Consultation under subsection (a)(3), and an opinion issued by the Secretary incident to such consultation, regarding an agency action shall be treated respectively as a consultation under subsection (a)(2), and as an opinion issued after consultation under such subsection, regarding that action if the Secretary reviews the action before it is commenced by the Federal agency and finds, and notifies such agency, that no significant changes have been made with respect to the action and that no significant change has occurred regarding the information used during the initial consultation."],[0,"(4) If after consultation under subsection (a)(2), the Secretary concludes that—"],[1,"(A) the agency action will not violate such subsection, or offers reasonable and prudent alternatives which the Secretary believes would not violate such subsection;"],[1,"(B) the taking of an endangered species or a threatened species incidental to the agency action will not violate such subsection; and"],[1,"(C) if an endangered species or threatened species of a marine mammal is involved, the taking is authorized pursuant to section 1371(a)(5) of this title;"],[0,"the Secretary shall provide the Federal agency and the applicant concerned, if any, with a written statement that—"],[1,"(i) specifies the impact of such incidental taking on the species,"],[1,"(ii) specifies those reasonable and prudent measures that the Secretary considers necessary or appropriate to minimize such impact,"],[1,"(iii) in the case of marine mammals, specifies those measures that are necessary to comply with section 1371(a)(5) of this title with regard to such taking, and"],[1,"(iv) sets forth the terms and conditions (including, but not limited to, reporting requirements) that must be complied with by the Federal agency or applicant (if any), or both, to implement the measures specified under clauses (ii) and (iii)."],[0,"(c) Biological assessment"],[0,"(1) To facilitate compliance with the requirements of subsection (a)(2), each Federal agency shall, with respect to any agency action of such agency for which no contract for construction has been entered into and for which no construction has begun on November 10, 1978, request of the Secretary information whether any species which is listed or proposed to be listed may be present in the area of such proposed action. If the Secretary advises, based on the best scientific and commercial data available, that such species may be present, such agency shall conduct a biological assessment for the purpose of identifying any endangered species or threatened species which is likely to be affected by such action. Such assessment shall be completed within 180 days after the date on which initiated (or within such other period as is mutually agreed to by the Secretary and such agency, except that if a permit or license applicant is involved, the 180-day period may not be extended unless such agency provides the applicant, before the close of such period, with a written statement setting forth the estimated length of the proposed extension and the reasons therefor) and, before any contract for construction is entered into and before construction is begun with respect to such action. Such assessment may be undertaken as part of a Federal agency's compliance with the requirements of section 102 of the National Environmental Policy Act of 1969 (42 U.S.C. 4332)."],[0,"(2) Any person who may wish to apply for an exemption under subsection (g) of this section for that action may conduct a biological assessment to identify any endangered species or threatened species which is likely to be affected by such action. Any such biological assessment must, however, be conducted in cooperation with the Secretary and under the supervision of the appropriate Federal agency."],[0,"(d) Limitation on commitment of resources"],[0,"After initiation of consultation required under subsection (a)(2), the Federal agency and the permit or license applicant shall not make any irreversible or irretrievable commitment of resources with respect to the agency action which has the effect of foreclosing the formulation or implementation of any reasonable and prudent alternative measures which would not violate subsection (a)(2) of this section."],[0,"(e) Endangered Species Committee"],[0,"(1) There is established a committee to be known as the Endangered Species Committee (hereinafter in this section referred to as the \"Committee\")."],[0,"(2) The Committee shall review any application submitted to it pursuant to this section and determine in accordance with subsection (h) of this section whether or not to grant an exemption from the requirements of subsection (a)(2) of this section for the action set forth in such application."],[0,"(3) The Committee shall be composed of seven members as follows:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1536?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 4, 4, 4","1":"passim, 8, 3, 8, 14, 25, 8, 23, 9","2":"5, 15, passim, 5, 9, 10, 15, 18, 18"},"q":[{"src":"brief","b":0,"text":"is not likely to jeopardize the continued existence of any endangered species or threatened species or result in the destruction or adverse modification of [critical] habitat.","cite":"16 U.S.C. 1536(a)(2)"},{"src":"brief","b":0,"text":"how the agency action affects the species or its critical habitat,","cite":"16 U.S.C. 1536(b)(3)(A)"},{"src":"brief","b":1,"text":"how the agency action affects the species or its critical habitat.","cite":"16 U.S.C. §1536(b)(3)(A)"},{"src":"brief","b":1,"text":"if jeopardy or adverse modification is found.","cite":"16 U.S.C. §1536(b)(3)(A)"},{"src":"brief","b":2,"text":"a written statement setting forth the Secretary’s opinion,","cite":"16 U.S.C. 1536(b)(3)(A)"}]},{"t":"usc","label":"16 U.S.C. § 1533","url":"https://www.law.cornell.edu/uscode/text/16/1533","subs":["(c)"],"stext":{"head":"§1533. Determination of endangered species and threatened species","paras":[[0,"(a) Generally"],[0,"(1) The Secretary shall by regulation promulgated in accordance with subsection (b) determine whether any species is an endangered species or a threatened species because of any of the following factors:"],[1,"(A) the present or threatened destruction, modification, or curtailment of its habitat or range;"],[1,"(B) overutilization for commercial, recreational, scientific, or educational purposes;"],[1,"(C) disease or predation;"],[1,"(D) the inadequacy of existing regulatory mechanisms; or"],[1,"(E) other natural or manmade factors affecting its continued existence."],[0,"(2) With respect to any species over which program responsibilities have been vested in the Secretary of Commerce pursuant to Reorganization Plan Numbered 4 of 1970—"],[1,"(A) in any case in which the Secretary of Commerce determines that such species should—"],[2,"(i) be listed as an endangered species or a threatened species, or"],[2,"(ii) be changed in status from a threatened species to an endangered species,"],[1,"he shall so inform the Secretary of the Interior; who shall list such species in accordance with this section;"],[1,"(B) in any case in which the Secretary of Commerce determines that such species should—"],[2,"(i) be removed from any list published pursuant to subsection (c) of this section, or"],[2,"(ii) be changed in status from an endangered species to a threatened species,"],[1,"he shall recommend such action to the Secretary of the Interior, and the Secretary of the Interior, if he concurs in the recommendation, shall implement such action; and"],[1,"(C) the Secretary of the Interior may not list or remove from any list any such species, and may not change the status of any such species which are listed, without a prior favorable determination made pursuant to this section by the Secretary of Commerce."],[0,"(3)(A) The Secretary, by regulation promulgated in accordance with subsection (b) and to the maximum extent prudent and determinable—"],[1,"(i) shall, concurrently with making a determination under paragraph (1) that a species is an endangered species or a threatened species, designate any habitat of such species which is then considered to be critical habitat; and"],[1,"(ii) may, from time-to-time thereafter as appropriate, revise such designation."],[0,"(B)(i) The Secretary shall not designate as critical habitat any lands or other geographical areas owned or controlled by the Department of Defense, or designated for its use, that are subject to an integrated natural resources management plan prepared under section 670a of this title, if the Secretary determines in writing that such plan provides a benefit to the species for which critical habitat is proposed for designation."],[0,"(ii) Nothing in this paragraph affects the requirement to consult under section 1536(a)(2) of this title with respect to an agency action (as that term is defined in that section)."],[0,"(iii) Nothing in this paragraph affects the obligation of the Department of Defense to comply with section 1538 of this title, including the prohibition preventing extinction and taking of endangered species and threatened species."],[0,"(b) Basis for determinations"],[0,"(1)(A) The Secretary shall make determinations required by subsection (a)(1) solely on the basis of the best scientific and commercial data available to him after conducting a review of the status of the species and after taking into account those efforts, if any, being made by any State or foreign nation, or any political subdivision of a State or foreign nation, to protect such species, whether by predator control, protection of habitat and food supply, or other conservation practices, within any area under its jurisdiction; or on the high seas."],[0,"(B) In carrying out this section, the Secretary shall give consideration to species which have been—"],[1,"(i) designated as requiring protection from unrestricted commerce by any foreign nation, or pursuant to any international agreement; or"],[1,"(ii) identified as in danger of extinction, or likely to become so within the foreseeable future, by any State agency or by any agency of a foreign nation that is responsible for the conservation of fish or wildlife or plants."],[0,"(2) The Secretary shall designate critical habitat, and make revisions thereto, under subsection (a)(3) on the basis of the best scientific data available and after taking into consideration the economic impact, the impact on national security, and any other relevant impact, of specifying any particular area as critical habitat. The Secretary may exclude any area from critical habitat if he determines that the benefits of such exclusion outweigh the benefits of specifying such area as part of the critical habitat, unless he determines, based on the best scientific and commercial data available, that the failure to designate such area as critical habitat will result in the extinction of the species concerned."],[0,"(3)(A) To the maximum extent practicable, within 90 days after receiving the petition of an interested person under section 553(e) of title 5, to add a species to, or to remove a species from, either of the lists published under subsection (c), the Secretary shall make a finding as to whether the petition presents substantial scientific or commercial information indicating that the petitioned action may be warranted. If such a petition is found to present such information, the Secretary shall promptly commence a review of the status of the species concerned. The Secretary shall promptly publish each finding made under this subparagraph in the Federal Register."],[0,"(B) Within 12 months after receiving a petition that is found under subparagraph (A) to present substantial information indicating that the petitioned action may be warranted, the Secretary shall make one of the following findings:"],[1,"(i) The petitioned action is not warranted, in which case the Secretary shall promptly publish such finding in the Federal Register."],[1,"(ii) The petitioned action is warranted, in which case the Secretary shall promptly publish in the Federal Register a general notice and the complete text of a proposed regulation to implement such action in accordance with paragraph (5)."],[1,"(iii) The petitioned action is warranted, but that—"],[2,"(I) the immediate proposal and timely promulgation of a final regulation implementing the petitioned action in accordance with paragraphs (5) and (6) is precluded by pending proposals to determine whether any species is an endangered species or a threatened species, and"],[2,"(II) expeditious progress is being made to add qualified species to either of the lists published under subsection (c) and to remove from such lists species for which the protections of this chapter are no longer necessary,"],[1,"in which case the Secretary shall promptly publish such finding in the Federal Register, together with a description and evaluation of the reasons and data on which the finding is based."],[0,"(C)(i) A petition with respect to which a finding is made under subparagraph (B)(iii) shall be treated as a petition that is resubmitted to the Secretary under subparagraph (A) on the date of such finding and that presents substantial scientific or commercial information that the petitioned action may be warranted."],[0,"(ii) Any negative finding described in subparagraph (A) and any finding described in subparagraph (B)(i) or (iii) shall be subject to judicial review."],[0,"(iii) The Secretary shall implement a system to monitor effectively the status of all species with respect to which a finding is made under subparagraph (B)(iii) and shall make prompt use of the authority under paragraph 7 1 to prevent a significant risk to the well being of any such species."],[0,"(D)(i) To the maximum extent practicable, within 90 days after receiving the petition of an interested person under section 553(e) of title 5, to revise a critical habitat designation, the Secretary shall make a finding as to whether the petition presents substantial scientific information indicating that the revision may be warranted. The Secretary shall promptly publish such finding in the Federal Register."],[0,"(ii) Within 12 months after receiving a petition that is found under clause (i) to present substantial information indicating that the requested revision may be warranted, the Secretary shall determine how he intends to proceed with the requested revision, and shall promptly publish notice of such intention in the Federal Register."],[0,"(4) Except as provided in paragraphs (5) and (6) of this subsection, the provisions of section 553 of title 5 (relating to rulemaking procedures), shall apply to any regulation promulgated to carry out the purposes of this chapter."],[0,"(5) With respect to any regulation proposed by the Secretary to implement a determination, designation, or revision referred to in subsection (a)(1) or (3), the Secretary shall—"],[1,"(A) not less than 90 days before the effective date of the regulation—"],[2,"(i) publish a general notice and the complete text of the proposed regulation in the Federal Register, and"],[2,"(ii) give actual notice of the proposed regulation (including the complete text of the regulation) to the State agency in each State in which the species is believed to occur, and to each county, or equivalent jurisdiction in which the species is believed to occur, and invite the comment of such agency, and each such jurisdiction, thereon;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1533?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5","1":"8"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(a)","(a)(2)(A)","(a)(2)(B)","(a)(4)(B)","(a)(8)(A)","(b)","(b)(5)","(a)(1)(B)","(a)(1)(D)","(a)(2)","(a)(2)(C)","(a)(2)(D)","(a)(3)","(a)(3)(A)","(a)(4)(A)(iii)","(b)(1)","(b)(7)","(b)(2)"],"stext":{"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","paras":[[0,"(a) Each agency shall make available to the public information as follows:"],[0,"(1) Each agency shall separately state and currently publish in the Federal Register for the guidance of the public—"],[1,"(A) descriptions of its central and field organization and the established places at which, the employees (and in the case of a uniformed service, the members) from whom, and the methods whereby, the public may obtain information, make submittals or requests, or obtain decisions;"],[1,"(B) statements of the general course and method by which its functions are channeled and determined, including the nature and requirements of all formal and informal procedures available;"],[1,"(C) rules of procedure, descriptions of forms available or the places at which forms may be obtained, and instructions as to the scope and contents of all papers, reports, or examinations;"],[1,"(D) substantive rules of general applicability adopted as authorized by law, and statements of general policy or interpretations of general applicability formulated and adopted by the agency; and"],[1,"(E) each amendment, revision, or repeal of the foregoing."],[0,"Except to the extent that a person has actual and timely notice of the terms thereof, a person may not in any manner be required to resort to, or be adversely affected by, a matter required to be published in the Federal Register and not so published. For the purpose of this paragraph, matter reasonably available to the class of persons affected thereby is deemed published in the Federal Register when incorporated by reference therein with the approval of the Director of the Federal Register."],[0,"(2) Each agency, in accordance with published rules, shall make available for public inspection in an electronic format—"],[1,"(A) final opinions, including concurring and dissenting opinions, as well as orders, made in the adjudication of cases;"],[1,"(B) those statements of policy and interpretations which have been adopted by the agency and are not published in the Federal Register;"],[1,"(C) administrative staff manuals and instructions to staff that affect a member of the public;"],[1,"(D) copies of all records, regardless of form or format—"],[2,"(i) that have been released to any person under paragraph (3); and"],[2,"(ii)(I) that because of the nature of their subject matter, the agency determines have become or are likely to become the subject of subsequent requests for substantially the same records; or"],[2,"(II) that have been requested 3 or more times; and"],[1,"(E) a general index of the records referred to under subparagraph (D);"],[0,"unless the materials are promptly published and copies offered for sale. For records created on or after November 1, 1996, within one year after such date, each agency shall make such records available, including by computer telecommunications or, if computer telecommunications means have not been established by the agency, by other electronic means. To the extent required to prevent a clearly unwarranted invasion of personal privacy, an agency may delete identifying details when it makes available or publishes an opinion, statement of policy, interpretation, staff manual, instruction, or copies of records referred to in subparagraph (D). However, in each case the justification for the deletion shall be explained fully in writing, and the extent of such deletion shall be indicated on the portion of the record which is made available or published, unless including that indication would harm an interest protected by the exemption in subsection (b) under which the deletion is made. If technically feasible, the extent of the deletion shall be indicated at the place in the record where the deletion was made. Each agency shall also maintain and make available for public inspection in an electronic format current indexes providing identifying information for the public as to any matter issued, adopted, or promulgated after July 4, 1967, and required by this paragraph to be made available or published. Each agency shall promptly publish, quarterly or more frequently, and distribute (by sale or otherwise) copies of each index or supplements thereto unless it determines by order published in the Federal Register that the publication would be unnecessary and impracticable, in which case the agency shall nonetheless provide copies of such index on request at a cost not to exceed the direct cost of duplication. Each agency shall make the index referred to in subparagraph (E) available by computer telecommunications by December 31, 1999. A final order, opinion, statement of policy, interpretation, or staff manual or instruction that affects a member of the public may be relied on, used, or cited as precedent by an agency against a party other than an agency only if—"],[1,"(i) it has been indexed and either made available or published as provided by this paragraph; or"],[1,"(ii) the party has actual and timely notice of the terms thereof."],[0,"(3)(A) Except with respect to the records made available under paragraphs (1) and (2) of this subsection, and except as provided in subparagraph (E), each agency, upon any request for records which (i) reasonably describes such records and (ii) is made in accordance with published rules stating the time, place, fees (if any), and procedures to be followed, shall make the records promptly available to any person."],[0,"(B) In making any record available to a person under this paragraph, an agency shall provide the record in any form or format requested by the person if the record is readily reproducible by the agency in that form or format. Each agency shall make reasonable efforts to maintain its records in forms or formats that are reproducible for purposes of this section."],[0,"(C) In responding under this paragraph to a request for records, an agency shall make reasonable efforts to search for the records in electronic form or format, except when such efforts would significantly interfere with the operation of the agency's automated information system."],[0,"(D) For purposes of this paragraph, the term \"search\" means to review, manually or by automated means, agency records for the purpose of locating those records which are responsive to a request."],[0,"(E) An agency, or part of an agency, that is an element of the intelligence community (as that term is defined in section 3(4) of the National Security Act of 1947 (50 U.S.C. 401a(4))) 1 shall not make any record available under this paragraph to—"],[1,"(i) any government entity, other than a State, territory, commonwealth, or district of the United States, or any subdivision thereof; or"],[1,"(ii) a representative of a government entity described in clause (i)."],[0,"(4)(A)(i) In order to carry out the provisions of this section, each agency shall promulgate regulations, pursuant to notice and receipt of public comment, specifying the schedule of fees applicable to the processing of requests under this section and establishing procedures and guidelines for determining when such fees should be waived or reduced. Such schedule shall conform to the guidelines which shall be promulgated, pursuant to notice and receipt of public comment, by the Director of the Office of Management and Budget and which shall provide for a uniform schedule of fees for all agencies."],[0,"(ii) Such agency regulations shall provide that—"],[1,"(I) fees shall be limited to reasonable standard charges for document search, duplication, and review, when records are requested for commercial use;"],[1,"(II) fees shall be limited to reasonable standard charges for document duplication when records are not sought for commercial use and the request is made by an educational or noncommercial scientific institution, whose purpose is scholarly or scientific research; or a representative of the news media; and"],[1,"(III) for any request not described in (I) or (II), fees shall be limited to reasonable standard charges for document search and duplication."],[0,"In this clause, the term \"a representative of the news media\" means any person or entity that gathers information of potential interest to a segment of the public, uses its editorial skills to turn the raw materials into a distinct work, and distributes that work to an audience. In this clause, the term \"news\" means information that is about current events or that would be of current interest to the public. Examples of news-media entities are television or radio stations broadcasting to the public at large and publishers of periodicals (but only if such entities qualify as disseminators of \"news\") who make their products available for purchase by or subscription by or free distribution to the general public. These examples are not all-inclusive. Moreover, as methods of news delivery evolve (for example, the adoption of the electronic dissemination of newspapers through telecommunications services), such alternative media shall be considered to be news-media entities. A freelance journalist shall be regarded as working for a news-media entity if the journalist can demonstrate a solid basis for expecting publication through that entity, whether or not the journalist is actually employed by the entity. A publication contract would present a solid basis for such an expectation; the Government may also consider the past publication record of the requester in making such a determination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552?type=usc&year=mostrecent&link-type=html"},"by":{"0":"13, 13, 13, 13, 13, 4, 47, 5, 5","1":"1, 20, 28, 48, 7, 38, 44, 48, 5, 28, 38, 5, 28, 39, 48, 5, 39, 48, 5, 38, 48, 5, 28, 45, passim, 6, 17, 20, 5, 42, 57, 2, 6, 21, 43, 56, 43, 44","2":"7, 7, 7, 22, 8, 1"},"q":[{"src":"brief","b":0,"text":"inter- agency or intra-agency memorandums or letters that would not be available by law to a party other than an agency in litigation with the agency.","cite":"5 U.S.C. 552(b)(5)"},{"src":"brief","b":0,"text":"inter-agency or intra-agency memorandums or letters that would not be available","cite":"5 U.S.C. 552(b)(5)"},{"src":"brief","b":1,"text":"administrative staff manuals and instructions to staff that affect a member of the public.","cite":"5 U.S.C. §§552(a)(2)(A)"},{"src":"brief","b":1,"text":"statements of policy and interpretations which have been adopted by the agency,","cite":"5 U.S.C. §§552(a)(2)(A)"},{"src":"brief","b":2,"text":"statements of policy and interpretations which have been adopted","cite":"5 U.S.C. 552(a)(2)(A)"}]},{"t":"reg","label":"51 Fed. Reg. 19,926","url":"https://www.govinfo.gov/link/fr/51/19926","by":{"0":"31","2":"5, 11, 12, 18"}},{"t":"reg","label":"76 Fed. Reg. 22,174","url":"https://www.govinfo.gov/link/fr/76/22174","by":{"0":"7","1":"12"}},{"t":"reg","label":"79 Fed. Reg. 48,300","url":"https://www.govinfo.gov/link/fr/79/48300","by":{"0":"11","1":"passim"}},{"t":"reg","label":"80 Fed. Reg. 26,832","url":"https://www.govinfo.gov/link/fr/80/26832","by":{"0":"6"}},{"t":"reg","label":"84 Fed. Reg. 44,976","url":"https://www.govinfo.gov/link/fr/84/44976","by":{"0":"6"}},{"t":"case","label":"Citizens to Preserve Overton Park v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"by":{"1":"16"}},{"t":"case","label":"Dep’t of Justice v. Reporters Comm. for Freedom of the Press","cite":"489 U.S. 749","y":1989,"id":"1988/87-1379","sc":1,"by":{"1":"1, 3, 4, 28, 45"},"q":[{"src":"brief","b":1,"text":"citizens’ right to be informed about ‘what their government is up to.’","cite":"489 U.S. 749, 773"}]},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. Railroads","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"Government officials [to] wield power without owning up to the consequences.","cite":"575 U.S. 43, 57"}]},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"by":{"1":"48"}},{"t":"case","label":"Doe 2 v. Shanahan","cite":"917 F.3d 694","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/917/694/","by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"It is the decision-making process that requires shielding from public scrutiny, not the decision itself once it has been acted on.","cite":"917 F.3d 694, 705"}]},{"t":"case","label":"Elec. Frontier Found. v. Dep’t of Justice","cite":"739 F.3d 1","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/739/1/","by":{"1":"56"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"‘unexplained inconsistency’ in agency policy is ‘a reason for holding [an action] to be . . . arbitrary and capricious,’","cite":"136 S. Ct. 2117, 2126"}]},{"t":"case","label":"Entergy Corp. v. Riverkeeper","cite":"556 U.S. 208","y":2009,"id":"2008/07-588","sc":1,"by":{"1":"12"}},{"t":"case","label":"FBI v. Abramson","cite":"456 U.S. 615","y":1982,"id":"1981/80-1735","sc":1,"by":{"1":"43"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"1":"38"}},{"t":"case","label":"GTE Sylvania v. Consumers Union","cite":"445 U.S. 375","y":1980,"id":"1979/78-1248","sc":1,"by":{"1":"4, 5, 21, 47, 51"}},{"t":"case","label":"Jordan v. Dep’t of Justice","cite":"591 F.2d 753","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/591/753/","by":{"1":"44"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"by":{"1":"27"}},{"t":"case","label":"Knight v. CIR","cite":"552 U.S. 181","y":2008,"id":"2007/06-1286","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"narrowly in order to preserve the primary operation of the [statutory] provision.","cite":"552 U.S. 181, 190-91"}]},{"t":"case","label":"Lagos v. United States","cite":"138 S. Ct. 1684","y":2018,"id":"2017/16-1519","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"statutory words are often known by the company they keep,","cite":"138 S. Ct. 1684, 1688-89"}]},{"t":"case","label":"Michigan v. EPA","cite":"135 S. Ct. 2699","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2699/","sc":1,"by":{"1":"30, 41"}},{"t":"case","label":"Milner v. Dep’t of Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"by":{"1":"5, 6, 43, 44","2":"8"},"q":[{"src":"brief","b":2,"text":"an all-purpose back-up provision to withhold sensitive records that do not fall within any of FOIA’s more targeted exemptions.","cite":"562 U.S. 562, 579"}]},{"t":"case","label":"Nat’l Archives & Records Admin. v. Favish","cite":"541 U.S. 157","y":2004,"id":"2003/02-954","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"dismiss[ ] as a convenient formalism,","cite":"541 U.S. 157, 171-72"}]},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Norton","cite":"309 F.3d 26","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/309/26/","by":{"1":"7"},"q":[{"src":"brief","b":1,"text":"‘reflect[ing] an agency’s preliminary positions or ruminations’ about a particular policy judgment,","cite":"309 F.3d 26, 39"}]},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"by":{"1":"32"}},{"t":"case","label":"Nat’l Council of La Raza v. Dep’t of Justice","cite":"411 F.3d 350","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/411/350/","by":{"1":"49"}},{"t":"case","label":"NLRB v. Robbins Tire & Rubber Co.","cite":"437 U.S. 214","y":1978,"id":"1977/77-911","sc":1,"by":{"1":"2, 4, 5, 29"},"q":[{"src":"brief","b":1,"text":"hold[ing] the governors accountable to the governed.","cite":"437 U.S. at 242"}]},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"by":{"1":"39"}},{"t":"case","label":"Public Citizen v. OMB","cite":"598 F.3d 865","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/598/865/","by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"an agency’s application of a policy to guide further decision-making does not render the policy itself predecisional.","cite":"598 F.3d 865, 875"}]},{"t":"case","label":"Schlefer v. United States","cite":"702 F.2d 233","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/702/233/","by":{"1":"50, 56"}},{"t":"case","label":"Sierra Club v. EPA","cite":"499 F.3d 653","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/499/653/","by":{"1":"51"}},{"t":"case","label":"Tax Analysts v. IRS","cite":"117 F.3d 607","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/117/607/","by":{"1":"7, 41, 49","2":"7"},"q":[{"src":"brief","b":1,"text":"statement[ ] of an agency’s legal position.","cite":"117 F.3d 607, 617"},{"src":"brief","b":1,"text":"[T]hat [documents] are nominally non-binding is no reason for treating them as something other than considered statements of the agency’s legal position.","cite":"117 F.3d at 617"}]},{"t":"case","label":"Taxation with Representation Fund v. IRS","cite":"646 F.2d 666","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/646/666/","by":{"1":"39"}},{"t":"case","label":"Thryv, Inc. v. Click-to-Call Techs.","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"by":{"1":"40, 45"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"by":{"1":"2, 8, 9, 34"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"by":{"1":"49"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)","(6)"],"by":{"1":"43, 38"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(A)"],"by":{"1":"39"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"20, 49"}},{"t":"usc","label":"16 U.S.C. § 1534-44","url":"https://www.law.cornell.edu/uscode/text/16/1534-44","by":{"1":"8"}},{"t":"usc","label":"33 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/33/1342","subs":["(d)(4)"],"by":{"1":"12, 15"}},{"t":"reg","label":"40 C.F.R. § 125.98","url":"https://www.ecfr.gov/current/title-40/section-125.98","subs":["(g)"],"by":{"1":"15, 26"}},{"t":"reg","label":"50 C.F.R. § 402.13","url":"https://www.ecfr.gov/current/title-50/section-402.13","subs":["(b)"],"by":{"1":"12, 10"}},{"t":"reg","label":"50 C.F.R. § 402.14","url":"https://www.ecfr.gov/current/title-50/section-402.14","subs":["(a)","(c)","(g)(1)","(g)(4)","(g)(5)","(g)(6)","(h)","(h)(2)"],"by":{"1":"10, 8, 10, 10, 10, 10, 21, 52, passim, 11, 11, 25"}},{"t":"case","label":"Dalton v. Specter","cite":"511 U.S. 462","y":1994,"id":"1993/93-289","sc":1,"by":{"2":"19"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"by":{"2":"19"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"by":{"2":"9"}},{"t":"case","label":"Oceana, Inc. v. Ross","cite":"920 F.3d 855","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/920/855/","by":{"2":"14"}},{"t":"case","label":"Swidler & Berlin v. United States","cite":"524 U.S. 399","y":1998,"id":"1997/97-1192","sc":1,"by":{"2":"19"}},{"t":"case","label":"Upjohn Co. v. United States","cite":"449 U.S. 383","y":1981,"id":"1980/79-886","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"would be an uncertain privilege, and as [this] Court has said, an uncertain privilege is ‘little better than no privilege at all.’","cite":"449 U.S. 383, 393"}]},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"2":"17"}},{"t":"usc","label":"16 U.S.C. § 1532","url":"https://www.law.cornell.edu/uscode/text/16/1532","subs":["(15)"],"stext":{"head":"§1532. Definitions","paras":[[0,"For the purposes of this chapter—"],[1,"(1) The term \"alternative courses of action\" means all alternatives and thus is not limited to original project objectives and agency jurisdiction."],[1,"(2) The term \"commercial activity\" means all activities of industry and trade, including, but not limited to, the buying or selling of commodities and activities conducted for the purpose of facilitating such buying and selling: Provided, however, That it does not include exhibition of commodities by museums or similar cultural or historical organizations."],[1,"(3) The terms \"conserve\", \"conserving\", and \"conservation\" mean to use and the use of all methods and procedures which are necessary to bring any endangered species or threatened species to the point at which the measures provided pursuant to this chapter are no longer necessary. Such methods and procedures include, but are not limited to, all activities associated with scientific resources management such as research, census, law enforcement, habitat acquisition and maintenance, propagation, live trapping, and transplantation, and, in the extraordinary case where population pressures within a given ecosystem cannot be otherwise relieved, may include regulated taking."],[1,"(4) The term \"Convention\" means the Convention on International Trade in Endangered Species of Wild Fauna and Flora, signed on March 3, 1973, and the appendices thereto."],[1,"(5)(A) The term \"critical habitat\" for a threatened or endangered species means—"],[2,"(i) the specific areas within the geographical area occupied by the species, at the time it is listed in accordance with the provisions of section 1533 of this title, on which are found those physical or biological features (I) essential to the conservation of the species and (II) which may require special management considerations or protection; and"],[2,"(ii) specific areas outside the geographical area occupied by the species at the time it is listed in accordance with the provisions of section 1533 of this title, upon a determination by the Secretary that such areas are essential for the conservation of the species."],[1,"(B) Critical habitat may be established for those species now listed as threatened or endangered species for which no critical habitat has heretofore been established as set forth in subparagraph (A) of this paragraph."],[1,"(C) Except in those circumstances determined by the Secretary, critical habitat shall not include the entire geographical area which can be occupied by the threatened or endangered species."],[1,"(6) The term \"endangered species\" means any species which is in danger of extinction throughout all or a significant portion of its range other than a species of the Class Insecta determined by the Secretary to constitute a pest whose protection under the provisions of this chapter would present an overwhelming and overriding risk to man."],[1,"(7) The term \"Federal agency\" means any department, agency, or instrumentality of the United States."],[1,"(8) The term \"fish or wildlife\" means any member of the animal kingdom, including without limitation any mammal, fish, bird (including any migratory, nonmigratory, or endangered bird for which protection is also afforded by treaty or other international agreement), amphibian, reptile, mollusk, crustacean, arthropod or other invertebrate, and includes any part, product, egg, or offspring thereof, or the dead body or parts thereof."],[1,"(9) The term \"foreign commerce\" includes, among other things, any transaction—"],[2,"(A) between persons within one foreign country;"],[2,"(B) between persons in two or more foreign countries;"],[2,"(C) between a person within the United States and a person in a foreign country; or"],[2,"(D) between persons within the United States, where the fish and wildlife in question are moving in any country or countries outside the United States."],[1,"(10) The term \"import\" means to land on, bring into, or introduce into, or attempt to land on, bring into, or introduce into, any place subject to the jurisdiction of the United States, whether or not such landing, bringing, or introduction constitutes an importation within the meaning of the customs laws of the United States."],[1,"(11) Repealed. Pub. L. 97–304, §4(b), Oct. 13, 1982, 96 Stat. 1420."],[1,"(12) The term \"permit or license applicant\" means, when used with respect to an action of a Federal agency for which exemption is sought under section 1536 of this title, any person whose application to such agency for a permit or license has been denied primarily because of the application of section 1536(a) of this title to such agency action."],[1,"(13) The term \"person\" means an individual, corporation, partnership, trust, association, or any other private entity; or any officer, employee, agent, department, or instrumentality of the Federal Government, of any State, municipality, or political subdivision of a State, or of any foreign government; any State, municipality, or political subdivision of a State; or any other entity subject to the jurisdiction of the United States."],[1,"(14) The term \"plant\" means any member of the plant kingdom, including seeds, roots and other parts thereof."],[1,"(15) The term \"Secretary\" means, except as otherwise herein provided, the Secretary of the Interior or the Secretary of Commerce as program responsibilities are vested pursuant to the provisions of Reorganization Plan Numbered 4 of 1970; except that with respect to the enforcement of the provisions of this chapter and the Convention which pertain to the importation or exportation of terrestrial plants, the term also means the Secretary of Agriculture."],[1,"(16) The term \"species\" includes any subspecies of fish or wildlife or plants, and any distinct population segment of any species of vertebrate fish or wildlife which interbreeds when mature."],[1,"(17) The term \"State\" means any of the several States, the District of Columbia, the Commonwealth of Puerto Rico, American Samoa, the Virgin Islands, Guam, and the Trust Territory of the Pacific Islands."],[1,"(18) The term \"State agency\" means any State agency, department, board, commission, or other governmental entity which is responsible for the management and conservation of fish, plant, or wildlife resources within a State."],[1,"(19) The term \"take\" means to harass, harm, pursue, hunt, shoot, wound, kill, trap, capture, or collect, or to attempt to engage in any such conduct."],[1,"(20) The term \"threatened species\" means any species which is likely to become an endangered species within the foreseeable future throughout all or a significant portion of its range."],[1,"(21) The term \"United States\", when used in a geographical context, includes all States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1532?type=usc&year=mostrecent&link-type=html"},"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"the Secretary of the Interior or the Secretary of Commerce,","cite":"16 U.S.C. 1532(15)"}]}]};